function searchResultsPage(data, origin, lang="id-ID", query="", page=1) {
  const en = lang === "en-US", results = data.results || [];
  const title = query ? (en ? `Search results for “${query}”` : `Hasil pencarian “${query}”`) : (en ? "Search movies" : "Cari Film");
  const desc = query ? (en ? `${data.total_results || 0} movie results for ${query}.` : `${data.total_results || 0} hasil film untuk ${query}.`) : (en ? "Search movies by title." : "Cari film berdasarkan judul.");
  const cards = results.map(m => {
    const name = m.title || m.original_title || (en ? "Untitled movie" : "Film tanpa judul");
    const poster = m.poster_path ? IMG + "w342" + esc(m.poster_path) : FALLBACK;
    const year = (m.release_date || "").slice(0,4);
    return `<a class="search-result-card" href="/movie/${m.id}-${slug(name)}"><img loading="lazy" src="${poster}" alt="${esc(name)}"><b>${esc(name)}</b><small>★ ${Number(m.vote_average || 0).toFixed(1)} · ${esc(year)}</small></a>`;
  }).join("");
  const prev = page > 1 ? `<a href="/search?query=${encodeURIComponent(query)}&page=${page-1}">← ${en ? "Previous" : "Sebelumnya"}</a>` : "<span></span>";
  const next = page < (data.total_pages || 0) ? `<a href="/search?query=${encodeURIComponent(query)}&page=${page+1}">${en ? "Next" : "Berikutnya"} →</a>` : "<span></span>";
  return `<!doctype html><html lang="${en ? "en" : "id"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} — ARLENNIZO</title><meta name="description" content="${esc(desc)}"><meta name="robots" content="noindex,follow"><link rel="canonical" href="${origin}/search${query ? `?query=${encodeURIComponent(query)}${page>1?`&page=${page}`:""}` : ""}"></head><body><main class="search-page"><div class="directory-kicker">ARLENNIZO · ${en ? "MOVIE SEARCH" : "PENCARIAN FILM"}</div><h1>${esc(title)}</h1><p class="search-summary">${esc(desc)}</p>${cards ? `<div class="search-results-grid">${cards}</div><nav class="search-pagination">${prev}<span>${en ? "Page" : "Halaman"} ${page} / ${data.total_pages || 1}</span>${next}</nav>` : `<div class="search-empty">${query ? (en ? "No movies found. Try another title." : "Film tidak ditemukan. Coba judul lain.") : (en ? "Enter a movie title in the search box above." : "Masukkan judul film pada kolom pencarian di atas.")}</div>`}</main></body></html>`;
}

async function relatedPeople(person, env) {
  const credits=(person.movie_credits?.cast||[]).filter(x=>x.id).sort((a,b)=>(b.popularity||0)-(a.popularity||0));
  const movies=[...new Map(credits.map(x=>[x.id,x])).values()].slice(0,6);
  const results=await Promise.all(movies.map(m=>tmdb(`/movie/${m.id}/credits`,env,{language:"en-US"}).catch(()=>null)));
  const people=new Map();
  for(const result of results) for(const member of result?.cast||[]) {
    if(!member.id||member.id===person.id||!member.profile_path) continue;
    const current=people.get(member.id)||{id:member.id,name:member.name,profile_path:member.profile_path,known_for_department:member.known_for_department||"Acting",count:0,popularity:0};
    current.count++;current.popularity=Math.max(current.popularity,member.popularity||0);people.set(member.id,current);
  }
  return [...people.values()].sort((a,b)=>b.count-a.count||b.popularity-a.popularity).slice(0,12);
}

