  const bio=(p.biography||"").trim()||"Biography is not available in TMDB for this person.";
  const schema={"@context":"https://schema.org","@type":"Person",name,url:canonical,image:photo,description:bio,birthDate:p.birthday||undefined,birthPlace:p.place_of_birth||undefined};
